"""Writes site/js/takehome.js from the files in this folder (the 'Take it home' project shown in 8g).
.py files cannot be hosted on the site, so they travel inside a .js file as text. Usage: python3 tools/takehome/build.py"""
import json, pathlib
HERE = pathlib.Path(__file__).resolve().parent
FILES = [('README.md', 'what to run, in order'), ('requirements.txt', 'pip install -r requirements.txt'), ('train.py', 'Steps 1-3: split, features + scikit-learn, Keras CNN, blend, gates'),
         ('flow.py', 'Steps 5 + 8: LangGraph flow, the one trial, interval, drift'), ('crew.py', 'Step 6: CrewAI crew + number guardrail'), ('app.py', 'Step 7: Gradio operator console'),
         ('.devcontainer/devcontainer.json', 'optional: GitHub Codespaces setup (VS Code in the browser)')]
out = {'note': 'Verified: train.py (2 epochs), flow.py (validation shift, the trial, the refusal of a second trial), crew.py --dry and app.py --smoke all ran in real Python (numpy, scikit-learn, Keras 3, LangGraph, CrewAI, Gradio) on the ELPV photos.',
       'files': [{'name': n, 'what': w, 'text': (HERE / pathlib.Path(n).name).read_text()} for n, w in FILES]}
js = '/* generated by tools/takehome/build.py — do not edit by hand */\nwindow.PG_TAKEHOME = ' + json.dumps(out, ensure_ascii=False) + ';\n'
(HERE.parent.parent / 'site/js/takehome.js').write_text(js.replace('</script', '<\\/script'))
print('takehome.js', len(js), 'bytes,', len(FILES), 'files')
